// Query syntax (SQL-like)
var querySyntax = from p in context.Products
                 where p.Price > 100 && p.IsActive
                 orderby p.Name
                 select p;

// Method syntax (more common in EF Core)
var methodSyntax = context.Products
    .Where(p => p.Price > 100 && p.IsActive)
    .OrderBy(p => p.Name);

// AND conditions (chained Where clauses are combined)
var activeElectronics = await context.Products
    .Where(p => p.Price > 100)
    .Where(p => p.Category.Name == "Electronics")
    .ToListAsync();

// OR condition (use || within a single Where)
var cheapOrFeatured = await context.Products
    .Where(p => p.Price < 20 || p.IsFeatured)
    .ToListAsync();

// String methods are translated to SQL LIKE
var searchResults = await context.Products
    .Where(p => p.Name.Contains("laptop"))
    .ToListAsync();

// Anonymous type projection
var productList = await context.Products
    .Where(p => p.IsActive)
    .Select(p => new { p.Name, p.Price, Category = p.Category.Name })
    .ToListAsync();

// DTO projection
var productDtos = await context.Products
    .Where(p => p.IsActive)
    .Select(p => new ProductDto
    {
        Name = p.Name,
        Price = p.Price,
        CategoryName = p.Category.Name
    })
    .ToListAsync();

var productWithCategory = await context.Products
    .Include(p => p.Category)
        .ThenInclude(c => c.Products)
    .FirstOrDefaultAsync(p => p.Id == 1);

if (productWithCategory?.Category != null)
{
    Console.WriteLine($"Product: {productWithCategory.Name}");
    Console.WriteLine($"Category: {productWithCategory.Category.Name}");
    Console.WriteLine($"Products in same category: {productWithCategory.Category.Products.Count}");
}

int pageSize = 10;
int pageNumber = 3;

var page = await context.Products
    .Where(p => p.IsActive)
    .OrderBy(p => p.Name) // required for pagination
    .Skip((pageNumber - 1) * pageSize)
    .Take(pageSize)
    .Select(p => new { p.Name, p.Price })
    .ToListAsync();

Console.WriteLine($"Showing page {pageNumber}, {page.Count} items");
